def check_eq1(a, b):
    # Equation 1: 5^b - 2^a = 50
    if 5**b - 2**a == 50:
        print(f"Solution found for 5^b - 2^a = 50: a={a}, b={b}")
        return True
    return False

def check_eq2(a, b):
    # Equation 2: 2^a - 5^b = 50
    if 2**a - 5**b == 50:
        print(f"Solution found for 2^a - 5^b = 50: a={a}, b={b}")
        return True
    return False

# Check Eq 1: 5^b - 2^a = 50
print("--- Checking 5^b - 2^a = 50 ---")
# Limit search: a up to 15 (2^15 = 32768), b up to 10 (5^10 ~ 10^7)
# Since 5^b = 50 + 2^a, b must be slightly larger than log5(2^a) = a log5(2) ~ 0.43a
for a in range(0, 16):
    for b in range(1, 11):
        if 5**b - 2**a == 50:
            check_eq1(a, b)

# Check Eq 2: 2^a - 5^b = 50
print("\n--- Checking 2^a - 5^b = 50 ---")
# Limit search: a up to 20 (2^20 ~ 10^6), b up to 7 (5^7 = 78125)
